-- Canonical architecture §§3, 5, 34, 36–38. Runtime role is not table owner.
CREATE TABLE tenant (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE company (tenant_id uuid NOT NULL REFERENCES tenant(id), id uuid NOT NULL, name text NOT NULL, currency char(3) NOT NULL DEFAULT 'XAF' CHECK(currency='XAF'), PRIMARY KEY(tenant_id,id));
CREATE TABLE branch (tenant_id uuid NOT NULL, company_id uuid NOT NULL, id uuid NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Africa/Douala', PRIMARY KEY(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id));
CREATE TABLE tenant_memberships (tenant_id uuid NOT NULL, actor_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, active boolean NOT NULL DEFAULT true, authorization_epoch bigint NOT NULL DEFAULT 1 CHECK(authorization_epoch>0), role_code text NOT NULL, PRIMARY KEY(tenant_id,actor_id,company_id,branch_id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE warehouse (tenant_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, id uuid NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,branch_id,id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE catalog_product (tenant_id uuid NOT NULL, company_id uuid NOT NULL, id uuid NOT NULL, sku text NOT NULL, name text NOT NULL, base_unit text NOT NULL, tax_basis_points integer NOT NULL DEFAULT 0 CHECK(tax_basis_points BETWEEN 0 AND 10000), selling_price_xaf bigint NOT NULL CHECK(selling_price_xaf>=0), active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,sku), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id));
CREATE TABLE stock_balance (tenant_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, warehouse_id uuid NOT NULL, product_id uuid NOT NULL, ownership_kind text NOT NULL DEFAULT 'MERCHANT' CHECK(ownership_kind='MERCHANT'), condition text NOT NULL DEFAULT 'SERVICEABLE' CHECK(condition='SERVICEABLE'), quantity_milli bigint NOT NULL DEFAULT 0 CHECK(quantity_milli>=0), reserved_milli bigint NOT NULL DEFAULT 0 CHECK(reserved_milli>=0), allocated_milli bigint NOT NULL DEFAULT 0 CHECK(allocated_milli>=0), value_xaf bigint NOT NULL DEFAULT 0 CHECK(value_xaf>=0), version bigint NOT NULL DEFAULT 0, CHECK(reserved_milli::numeric+allocated_milli::numeric<=quantity_milli), PRIMARY KEY(tenant_id,company_id,warehouse_id,product_id), FOREIGN KEY(tenant_id,company_id,branch_id,warehouse_id) REFERENCES warehouse(tenant_id,company_id,branch_id,id), FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
CREATE TABLE stock_movement (tenant_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, id uuid NOT NULL, warehouse_id uuid NOT NULL, product_id uuid NOT NULL, quantity_milli bigint NOT NULL CHECK(quantity_milli<>0), value_xaf bigint NOT NULL, actor_id uuid NOT NULL, operation_id uuid NOT NULL, reason text NOT NULL CHECK(length(trim(reason))>0), occurred_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,company_id,operation_id,product_id,warehouse_id), FOREIGN KEY(tenant_id,company_id,branch_id,warehouse_id) REFERENCES warehouse(tenant_id,company_id,branch_id,id), FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
CREATE TABLE financial_period (tenant_id uuid NOT NULL, company_id uuid NOT NULL, id uuid NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status text NOT NULL CHECK(status IN ('Open','Closed')), CHECK(start_date<=end_date), PRIMARY KEY(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id));
CREATE TABLE customer (tenant_id uuid NOT NULL, company_id uuid NOT NULL, id uuid NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id));
CREATE TABLE sale (tenant_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, id uuid NOT NULL, operation_id uuid NOT NULL, warehouse_id uuid NOT NULL, customer_id uuid, actor_id uuid NOT NULL, business_date date NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','HELD','POSTED','PARTIALLY_RETURNED','FULLY_RETURNED','VOIDED_BEFORE_POST')), currency char(3) NOT NULL DEFAULT 'XAF' CHECK(currency='XAF'), total_xaf bigint NOT NULL DEFAULT 0 CHECK(total_xaf>=0), cost_xaf bigint NOT NULL DEFAULT 0 CHECK(cost_xaf>=0), version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,company_id,id), UNIQUE(tenant_id,operation_id), FOREIGN KEY(tenant_id,company_id,customer_id) REFERENCES customer(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,branch_id,warehouse_id) REFERENCES warehouse(tenant_id,company_id,branch_id,id));
CREATE TABLE sale_line (tenant_id uuid NOT NULL, company_id uuid NOT NULL, sale_id uuid NOT NULL, id uuid NOT NULL, product_id uuid NOT NULL, quantity_milli bigint NOT NULL CHECK(quantity_milli>0), unit_price_xaf bigint NOT NULL CHECK(unit_price_xaf>=0), line_total_xaf bigint NOT NULL CHECK(line_total_xaf>=0), cost_xaf bigint NOT NULL DEFAULT 0 CHECK(cost_xaf>=0), PRIMARY KEY(tenant_id,company_id,sale_id,id), FOREIGN KEY(tenant_id,company_id,sale_id) REFERENCES sale(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
CREATE TABLE journal_entry (tenant_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, id uuid NOT NULL, operation_id uuid NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL, created_transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(), business_date date NOT NULL, currency char(3) NOT NULL DEFAULT 'XAF' CHECK(currency='XAF'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,operation_id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE journal_line (tenant_id uuid NOT NULL, company_id uuid NOT NULL, entry_id uuid NOT NULL, id uuid NOT NULL, account_code text NOT NULL, debit_xaf bigint NOT NULL DEFAULT 0 CHECK(debit_xaf>=0), credit_xaf bigint NOT NULL DEFAULT 0 CHECK(credit_xaf>=0), CHECK((debit_xaf>0 AND credit_xaf=0) OR (credit_xaf>0 AND debit_xaf=0)), PRIMARY KEY(tenant_id,company_id,entry_id,id), FOREIGN KEY(tenant_id,company_id,entry_id) REFERENCES journal_entry(tenant_id,company_id,id));
CREATE TABLE idempotency_result (tenant_id uuid NOT NULL, operation_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, request_hash text NOT NULL CHECK(length(request_hash)=64), source_type text, source_id uuid, response_json jsonb, actor_id uuid DEFAULT nullif(current_setting('app.actor_id',true),'')::uuid, status text NOT NULL DEFAULT 'ACCEPTED' CHECK(status IN ('ACCEPTED','REJECTED')), response_expires_at timestamptz DEFAULT now()+interval '90 days', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,operation_id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE outbox_event (tenant_id uuid NOT NULL, id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, operation_id uuid NOT NULL, event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE outbox_delivery (tenant_id uuid NOT NULL, event_id uuid NOT NULL, consumer_name text NOT NULL, lease_owner text, fencing_token bigint NOT NULL DEFAULT 0, lease_expires_at timestamptz, attempt integer NOT NULL DEFAULT 0, next_retry_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, PRIMARY KEY(tenant_id,consumer_name,event_id), FOREIGN KEY(tenant_id,event_id) REFERENCES outbox_event(tenant_id,id));
CREATE TABLE inbox_receipt (tenant_id uuid NOT NULL, consumer_name text NOT NULL, event_id uuid NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,consumer_name,event_id), FOREIGN KEY(tenant_id,event_id) REFERENCES outbox_event(tenant_id,id));
CREATE TABLE tenant_change_clock (tenant_id uuid PRIMARY KEY REFERENCES tenant(id), sequence bigint NOT NULL DEFAULT 0 CHECK(sequence>=0));
CREATE TABLE change_batch (tenant_id uuid NOT NULL, sequence bigint NOT NULL CHECK(sequence>0), operation_id uuid NOT NULL, company_id uuid NOT NULL, branch_id uuid NOT NULL, schema_version integer NOT NULL, payload jsonb NOT NULL, digest text NOT NULL CHECK(length(digest)=64), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,sequence), UNIQUE(tenant_id,operation_id), FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE INDEX sale_register ON sale(tenant_id,company_id,branch_id,created_at DESC,id);
CREATE INDEX stock_movement_register ON stock_movement(tenant_id,company_id,branch_id,occurred_at DESC,id);
CREATE INDEX outbox_retry ON outbox_delivery(next_retry_at) WHERE completed_at IS NULL;
